package com.amdocs.telecom.service; import com.amdocs.telecom.util.DBConnection;import com.amdocs.telecom.security.*;import com.amdocs.telecom.model.Types.Role;import java.sql.*;import java.util.*;import java.util.concurrent.*;
public class AuthService{public static class Challenge{public String username,role,refId,otp;Challenge(String u,String r,String id,String o){username=u;role=r;refId=id;otp=o;}}private final OTPService otp=new OTPService();private final ConcurrentMap<String,AuthContext> sessions=new ConcurrentHashMap<>();public Challenge passwordStep(String u,String p,String ip)throws SQLException{try(Connection c=DBConnection.getInstance().get()){String hash=null,role=null,ref=null;int fails=0;Timestamp locked=null;try(PreparedStatement q=c.prepareStatement("SELECT password_hash,role,ref_id,failed_attempts,locked_until FROM users WHERE username=?")){q.setString(1,u);try(ResultSet r=q.executeQuery()){if(r.next()){hash=r.getString(1);role=r.getString(2);ref=r.getString(3);fails=r.getInt(4);locked=r.getTimestamp(5);}}}if(hash==null||locked!=null&&locked.after(new Timestamp(System.currentTimeMillis()))||!PasswordUtil.verify(p,hash)){if(hash!=null){fails++;try(PreparedStatement q=c.prepareStatement("UPDATE users SET failed_attempts=?,locked_until=? WHERE username=?")){q.setInt(1,fails);q.setTimestamp(2,fails>=5?new Timestamp(System.currentTimeMillis()+15*60*1000):null);q.setString(3,u);q.executeUpdate();}}history(c,u,false,ip,"Password rejected or account locked");throw new SecurityException("Invalid credentials or account locked");}try(PreparedStatement q=c.prepareStatement("UPDATE users SET failed_attempts=0,locked_until=NULL WHERE username=?")){q.setString(1,u);q.executeUpdate();}return new Challenge(u,role,ref,otp.issue(u));}}public String otpStep(String u,String o)throws SQLException{if(!otp.verify(u,o))throw new SecurityException("Invalid or expired OTP");try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement("SELECT role,ref_id FROM users WHERE username=?")){p.setString(1,u);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SecurityException("Unknown user");String token=UUID.randomUUID().toString();sessions.put(token,new AuthContext(u,Role.valueOf(r.getString(1)),r.getString(2)));history(c,u,true,"api","OTP verified");return token;}}}public AuthContext get(String t){return sessions.get(t);}public void logout(String t){sessions.remove(t);}private void history(Connection c,String u,boolean s,String ip,String rem)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO login_history(username,success,ip_address,remarks) VALUES(?,?,?,?)")){p.setString(1,u);p.setBoolean(2,s);p.setString(3,ip);p.setString(4,rem);p.executeUpdate();}}}
